function* counter() {
  console.log('Start!');
  yield 1; // Pause execution (return value 1)
  console.log('Resumed!');
  yield 2; // Pause execution (return value 2)
  console.log('Done!');
}

// Calling the function doesn't run it — it returns an Iterator (control object)
const gen = counter();

console.log(gen.next()); // { value: 1, done: false }
console.log(gen.next()); // { value: 2, done: false }
console.log(gen.next()); // { value: undefined, done: true }
